<script lang="ts">
 import {fixtureMetadataLines,enrichFixtureMetadata} from '#lib/fixture-metadata.js';
 import {recordActivity} from '#lib/activity.ts';
 import {app} from '#lib/state.svelte.ts';
 import {feed} from '#lib/feed.svelte.ts';
 import {SPORTS,SPORT_ORDER} from '#lib/sports.ts';
 import {machineCandidates,buildMachineTicket,buildModelShortlist,MACHINE_MARKET_FILTERS,machineFixtureKey} from '#lib/bet-machine.js';
 import {odds,pct} from '#lib/format.ts';
 import Accordion from '#lib/components/Accordion.svelte';
 import DataBadge from '#lib/components/DataBadge.svelte';
 import {auth} from '#lib/auth.svelte.ts';
 import {anyApi} from 'convex/server';
 import {tick,untrack,onDestroy} from 'svelte';
 let savedRules=$state<any[]|null>(null),ruleName=$state(''),ruleBusy=$state(false),ruleMessage=$state('');
 $effect(()=>{const client=auth.client;savedRules=null;if(!client)return;return client.onUpdate(anyApi.ticketRules.list,{},r=>savedRules=r,()=>ruleMessage='Saved rules could not load. Check your connection.');});
 let sports=$state<string[]>([...SPORT_ORDER]),markets=$state<string[]>([]),direction=$state('all'),window=$state('12');
 let targetOdds=$state(5);
 const minOdds=1.01;const maxOdds=$derived(targetOdds*1.05);const minTotal=$derived(targetOdds);const maxTotal=$derived(targetOdds*1.05);
 let minProbability=$state(55),positiveValue=$state(false);
 let dateFrom=$state(''),dateTo=$state('');
 let shortlisted=$state<ReturnType<typeof machineCandidates>>([]),shortlistLimit=$state(30);
 let ticket=$state<ReturnType<typeof buildMachineTicket>>(null),error=$state(''),generatedAt=$state(0);
 let modelShortlist=$state(false),notice=$state('');
 let generating=$state(false),history=$state<string[]>([]),request=0,worker:Worker|undefined;
 let cancelSearch:(()=>void)|undefined;
 function cancel(){request++;worker?.terminate();worker=undefined;cancelSearch?.();cancelSearch=undefined;generating=false;}
 onDestroy(cancel);
 const marketOptions=$derived([...MACHINE_MARKET_FILTERS,...new Map(app.all.flatMap(p=>p.markets.map(g=>[g.key,g.title] as const))).entries()]);
 const publishedIds=$derived(new Set((feed.data?.projections??[]).filter(p=>p.state==='scheduled').map(p=>p.fixtureId)));
 function timeRange() {
  const now=Date.now();
  if(window==='custom')return {from:Date.parse(`${dateFrom}:00+01:00`),to:Date.parse(`${dateTo}:00+01:00`)};
  return {from:now,to:now+Number(window)*3600000};
 }
 $effect(()=>{sports;markets;direction;window;minOdds;maxOdds;minTotal;maxTotal;minProbability;positiveValue;dateFrom;dateTo;untrack(cancel);history=[];ticket=null;modelShortlist=false;notice='';shortlisted=[];error='';});
 $effect(()=>{if(!feed.data)ticket=null;});
 const candidateCount=$derived(app.all.filter(p=>publishedIds.has(p.fixtureId)&&p.status.state==='scheduled').length);
 async function generate(){if(generating)return;error='';notice='';generating=true;const current=++request;try{await tick();await new Promise(resolve=>setTimeout(resolve,0));if(current!==request)return;const range=timeRange();if(![minOdds,maxOdds,minTotal,maxTotal,minProbability].every(Number.isFinite)||!Number.isFinite(range.from)||!Number.isFinite(range.to)||range.to<range.from||minOdds<1.01||maxOdds<minOdds||minProbability<1||minProbability>99)throw new Error('Check your date, odds and probability ranges.');const candidates=machineCandidates(app.all,{...range,publishedIds,sports,markets,direction,minOdds,maxOdds,includeUnpriced:true,minProbability:minProbability/100,positiveValue,sportStats:feed.data?.record.summary.sports},Date.now());shortlisted=candidates;shortlistLimit=30;if(typeof Worker==='undefined')throw Error('Background ticket search is unavailable in this browser. Update your browser to generate tickets.');const active=new Worker(new URL('../../lib/bet-machine.worker.js',import.meta.url),{type:'module'});worker=active;const result=await new Promise<ReturnType<typeof buildMachineTicket>>((resolve,reject)=>{const timer=setTimeout(()=>{active.terminate();reject(Error('Search took too long. Narrow the selected sports or markets and try again.'));},15000);const finish=()=>{clearTimeout(timer);active.terminate();if(worker===active)worker=undefined;cancelSearch=undefined;};cancelSearch=()=>{clearTimeout(timer);resolve(null);};active.onmessage=e=>{finish();if(e.data.error)reject(Error(e.data.error));else resolve(e.data.ticket);};active.onerror=()=>{finish();reject(Error('Background search could not start. Reload the application and try again.'));};active.postMessage({candidates:$state.snapshot(candidates),options:{minTotal,maxTotal,excludeFixtures:$state.snapshot(history)}});});if(current!==request)return;if(!result){if(history.length&&ticket&&!modelShortlist){notice='No further quoted fixture combination was found within this search. Your previous accumulator is kept. All matching options remain available below.';return;}ticket=buildModelShortlist(candidates);modelShortlist=!!ticket;generatedAt=Date.now();const quoted=candidates.filter(p=>p.pricing==='quoted'&&Number.isFinite(p.bestOdds)&&p.bestOdds>1).length;if(ticket){notice=quoted===0?`${candidates.length} options meet your filters, but none has an available bookmaker quote. Preview shows the highest model probability per fixture; the odds target cannot be calculated.`:`${quoted} quoted options were searched, but no combination reached ${minTotal}–${maxTotal.toFixed(2)} in the bounded search. Preview shows a model shortlist; it does not meet your odds target.`;}else{error='No upcoming published options meet all your filters. Try a wider kickoff window or different sports and markets.';}return;}ticket=result;modelShortlist=false;history=[...history,result.fixtureKey];generatedAt=Date.now();recordActivity('ticket_generated');}catch(e){if(current===request)error=(e as Error).message;}finally{if(current===request)generating=false;}}
 function preview(){if(!ticket)return;const valid=ticket.picks.every(p=>{const current=app.byId(p.fixtureId);return current?.status.state==='scheduled'&&Date.parse(current.kickoffTime)>Date.now()&&current.markets.some(g=>g.selections.some(s=>s.id===p.id&&(p.pricing==='quoted'?s.pricing==='quoted'&&Math.abs(s.bestOdds-p.bestOdds)<.001:s.pricing!=='quoted')));});if(!valid){error='A fixture started or its quote changed. Generate a fresh ticket before previewing.';return;}app.clearSlip();for(const pick of ticket.picks)app.toggle(pick as any);app.slipOpen=true;}
 function choose(pick:any){const current=app.byId(pick.fixtureId)?.markets.flatMap(g=>g.selections).find(s=>s.id===pick.id);if(app.inSlip(pick.id)){app.remove(pick.id);return;}if(!current||(current.pricing==='quoted'&&Math.abs(current.bestOdds-pick.bestOdds)>.001)){error='This quote changed. Generate the shortlist again.';return;}const eventKey=machineFixtureKey(app.byId(pick.fixtureId)!);for(const leg of app.slip){const fixture=app.byId(leg.fixtureId);if(fixture&&machineFixtureKey(fixture)===eventKey)app.remove(leg.id);}if(!app.toggle({...current,evidence:pick.evidence} as any))error='This fixture is no longer available before kickoff.';}
 function showSaved(){const details=document.querySelector<HTMLDetailsElement>('#saved-ticket-rules details');if(details){details.open=true;details.querySelector('summary')?.focus();}}
 async function saveRules(){if(!auth.client){ruleMessage='Sign in to save rules to your account. Your current filters remain on this page.';return;}ruleBusy=true;ruleMessage='';try{await auth.client.mutation(anyApi.ticketRules.save,{name:ruleName,rules:{sports,markets,direction,window,minOdds,maxOdds,minTotal,maxTotal,targetOdds,minProbability,positiveValue,dateFrom,dateTo}});recordActivity('rules_saved');ruleMessage='Rules saved. Open Saved ticket rules to reuse them against the latest fixtures.';}catch(e){ruleMessage=(e as Error).message;}finally{ruleBusy=false;}}
 async function reuse(row:any){const r=row.rules;sports=[...r.sports];markets=[...r.markets];direction=r.direction;window=['today','tomorrow'].includes(r.window)?(r.window==='today'?'24':'48'):r.window;targetOdds=r.targetOdds??r.minTotal;minProbability=r.minProbability;positiveValue=r.positiveValue;dateFrom=r.dateFrom;dateTo=r.dateTo;ruleName=row.name;await tick();untrack(generate);}
 async function deleteRules(id:any){if(!auth.client)return;ruleBusy=true;try{await auth.client.mutation(anyApi.ticketRules.remove,{id});}catch(e){ruleMessage=(e as Error).message;}finally{ruleBusy=false;}}
</script>
<svelte:head><title>Advanced bet machine — PuntersEdge</title><meta name="robots" content="noindex" /></svelte:head>
<header><p class="text-sm font-semibold uppercase tracking-widest text-model">Build with the model</p><div class="mt-2 flex flex-wrap items-center gap-3"><h1 class="text-4xl font-bold">Advanced bet machine</h1><DataBadge /></div><p class="mt-3 max-w-3xl text-haze">Generate a ticket from published pre-match forecasts and actual quoted markets. The probability optimizer compares eligible combinations; it uses the quantitative engines rather than asking an LLM to invent picks.</p></header>
<div id="saved-ticket-rules" class="scroll-mt-24"><Accordion title="Saved ticket rules" count={savedRules?.length??0}><p class="text-sm text-haze">Reuse a rule set to generate a fresh shortlist from current fixtures. Relative time windows roll forward; custom dates stay fixed.</p><ul class="mt-4 grid gap-2 sm:grid-cols-2">{#each savedRules??[] as row(row._id)}<li class="flex min-w-0 items-center gap-2 rounded-xl border border-line p-3"><button class="min-h-11 min-w-0 flex-1 text-left" onclick={()=>reuse(row)}><strong class="block break-words text-sm">{row.name}</strong><span class="text-xs text-haze">Load rules & generate current matches ↗</span></button><button class="btn-ghost text-xs" disabled={ruleBusy} onclick={()=>deleteRules(row._id)} aria-label="Delete rules {row.name}">Delete</button></li>{:else}<li class="text-sm text-haze">{!auth.client?'Sign in to load your saved rules.':savedRules===null?'Loading your saved rules…':'No rules saved yet. Name and save your current rules below.'}</li>{/each}</ul></Accordion></div>
<div class="mt-6 grid gap-5 lg:grid-cols-[1.1fr_1fr]">
<section class="surface p-5"><h2 class="text-xl font-bold">Your ticket rules</h2><p class="mt-1 text-sm text-haze">{candidateCount} published upcoming fixtures available.</p>
<Accordion title="Sports & market choices">
 <fieldset><legend class="text-sm font-semibold">Sports</legend><div class="mt-2 flex flex-wrap gap-3">{#each SPORT_ORDER as s}<label class="flex min-h-10 items-center gap-2 text-sm"><input type="checkbox" value={s} bind:group={sports} />{SPORTS[s].label}</label>{/each}</div></fieldset>
 <fieldset class="mt-4"><legend class="text-sm font-semibold">Market types · none selected means all</legend><div class="mt-2 grid gap-2 sm:grid-cols-2">{#each marketOptions as [key,title]}<label class="flex items-center gap-2 text-sm"><input type="checkbox" value={key} bind:group={markets} />{title}</label>{/each}</div></fieldset>
 <label class="mt-4 block text-sm">Selection direction<select class="mt-1 w-full rounded-xl bg-ink p-3 ring-1 ring-line" bind:value={direction}><option value="all">Any direction</option><option value="home">Home-favoured fixtures</option><option value="away">Away-favoured fixtures</option><option value="over">Over markets</option><option value="under">Under markets</option><option value="draw">Draw</option></select></label>
</Accordion>
<Accordion title="Time & odds range">
 <label class="block text-sm">Kickoff window<select class="mt-1 w-full rounded-xl bg-ink p-3 ring-1 ring-line" bind:value={window}>{#each [1,3,6,12,24,48] as h}<option value={String(h)}>Next {h} hours</option>{/each}<option value="custom">Custom date and time · WAT</option></select></label>
 {#if window==='custom'}<div class="mt-3 grid gap-3 sm:grid-cols-2"><label class="text-sm">From<input type="datetime-local" class="mt-1 w-full min-w-0 rounded-xl bg-ink p-3 ring-1 ring-line" bind:value={dateFrom} /></label><label class="text-sm">To<input type="datetime-local" class="mt-1 w-full min-w-0 rounded-xl bg-ink p-3 ring-1 ring-line" bind:value={dateTo} /></label></div>{/if}
 <label class="mt-4 block text-sm">Target combined odds<input type="number" min="1.1" max="10000" step="0.1" bind:value={targetOdds} class="mt-1 min-h-11 w-full rounded-xl bg-ink p-3 ring-1 ring-line" /></label><div class="mt-3 flex flex-wrap gap-2">{#each [2,3,5,10,20] as target}<button class="btn-ghost" aria-pressed={targetOdds===target} onclick={()=>targetOdds=target}>{target} odds</button>{/each}</div><p class="mt-2 text-xs text-haze">Selects a combination from your chosen sports and markets, prioritizing model probability. Actual combined prices must reach your target and stay within 5% above it. An exact total may be unavailable.</p>
</Accordion>
<label class="mt-4 block text-sm">Minimum model %<input type="number" min="1" max="99" bind:value={minProbability} class="mt-1 w-full rounded-xl bg-ink p-3 ring-1 ring-line" /></label><p class="mt-2 text-xs text-haze">All matching fixtures appear below. A quoted accumulator chooses up to 30 distinct fixtures to reach your target odds, ranked by estimated all-win probability. If the target cannot be reached, the model shortlist includes every matching fixture, once.</p>
<p class="mt-4 text-xs text-haze">Probability-first mode can include prices with negative expected value. Enable the value filter to exclude those prices.</p>
<label class="mt-4 flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={positiveValue} />Only positive expected-value prices</label>
<button class="btn-primary mt-5 w-full" onclick={generate} disabled={generating} aria-busy={generating}>{generating?'Comparing eligible tickets…':history.length?'Generate a different accumulator':'Auto-generate accumulator'}</button><p class="mt-2 text-xs text-haze" role="status">{generating?'Searching in the background. You can keep using the page.':'Quoted accumulators use unseen fixture combinations ranked by estimated all-win probability. If prices cannot reach the target, preview shows the highest-ranked model shortlist.'}</p>{#if notice}<p role="status" class="mt-3 rounded-xl border border-line bg-ink p-3 text-sm text-book">{notice}</p>{/if}{#if error}<p role="alert" class="mt-3 text-sm text-loss">{error}</p>{/if}
<div class="mt-5 rounded-xl border border-line bg-ink p-4"><h3 class="font-semibold">Save these ticket rules</h3><p class="mt-1 text-xs text-haze">Save filters even when only a model shortlist is available. Reuse them with current fixtures next time.</p><label class="mt-3 block text-sm" for="ticket-rule-name">Rule name</label><input id="ticket-rule-name" class="mt-1 min-h-11 w-full rounded-xl border border-line bg-deep px-3" bind:value={ruleName} maxlength="60" placeholder="Weekend football shortlist"/><div class="mt-3 flex flex-wrap gap-2"><button class="btn-primary" onclick={saveRules} disabled={ruleBusy||!ruleName.trim()}>{ruleBusy?'Saving…':'Save current rules'}</button><a class="btn-ghost" href="#saved-ticket-rules" onclick={showSaved}>View saved rules · {savedRules?.length??0}</a></div>{#if ruleMessage}<p role="status" class="mt-3 text-sm text-model">{ruleMessage}</p>{/if}</div>
</section>
<section class="surface self-start p-5"><h2 class="text-xl font-bold">Ticket preview</h2>{#if ticket}<p class="mt-1 text-sm text-haze">{ticket.picks.length} fixtures · Model % high to low · {modelShortlist?'Model shortlist · target odds not reached':`Quoted accumulator · odds within ${minTotal}–${maxTotal.toFixed(2)}`}</p>{/if}{#if ticket}<div class="mt-4 grid grid-cols-2 gap-3"><div class="rounded-xl bg-ink p-4"><p class="text-xs text-haze">{modelShortlist?'Quoted subset odds':'Combined odds'}</p><p class="text-2xl font-bold text-book">{#if ticket.picks.some(p=>p.pricing==='quoted')}{odds(ticket.combinedOdds)}{:else}<span class="whitespace-nowrap text-lg">Unpriced</span>{/if}</p>{#if modelShortlist}<p class="mt-1 text-xs text-haze">Unpriced selections excluded · target {targetOdds}</p>{/if}</div><div class="rounded-xl bg-ink p-4"><p class="text-xs text-haze">Estimated all-win chance</p><p class="text-3xl font-bold text-model">{pct(ticket.combinedProbability,1)}</p></div></div><ol class="mt-4 grid gap-3">{#each ticket.picks as pick,i}<li class="option-card p-4"><a class="fixture-name block min-h-8 text-xs hover:underline" href="/match?id={encodeURIComponent(pick.fixtureId)}">{i+1}. {pick.matchTitle}</a><p class="mt-1 break-words text-xs text-haze">{fixtureMetadataLines(enrichFixtureMetadata(pick,app.gameById(pick.fixtureId))).join(' · ')}</p><p class="mt-1 break-words text-xs text-haze">{fixtureMetadataLines(enrichFixtureMetadata(pick,app.gameById(pick.fixtureId))).join(' · ')}</p><p class="mt-1 font-semibold">{pick.selection} <span class="text-book">@ {pick.pricing==='quoted'?odds(pick.bestOdds):'Unpriced'}</span></p><p class="mt-1 text-sm text-haze">Model {pct(pick.modelProb,1)} · Value grade {pick.grade} · {pick.pricing==='quoted'?pick.bookmaker:'Quote unavailable'}</p><Accordion title="Selection evidence & alternatives">
 <p class="text-sm text-haze">Basis: {pick.evidence.basis}. {pick.evidence.verdict?'Matches the model’s final verdict.':modelShortlist?'One of the highest model probabilities within your filters.':'Selected through the probability and odds constraints.'}</p>
 <dl class="mt-3 grid grid-cols-2 gap-2 text-xs"><dt>Model / market</dt><dd>{pct(pick.modelProb,1)} / {pick.evidence.marketProbability===null?'Unavailable':pct(pick.evidence.marketProbability,1)}</dd><dt>Break-even probability</dt><dd>{pick.evidence.breakEvenProbability===null?'Unavailable':pct(pick.evidence.breakEvenProbability,1)}</dd><dt>Expected value</dt><dd>{pick.pricing==='quoted'?`${pick.edgePercent.toFixed(1)}%`:'Unavailable without a quote'}</dd><dt>Quote observed</dt><dd>{pick.evidence.observedAt?new Date(pick.evidence.observedAt).toLocaleString('en-NG',{timeZone:'Africa/Lagos'}):'Timestamp unavailable; confirm the offer'}</dd></dl>
 <p class="mt-3 text-xs text-haze">{pick.evidence.settledSportPicks} retained sport verdicts settled{pick.evidence.sportWinRate===null?'':` · ${(pick.evidence.sportWinRate*100).toFixed(1)}% won (excluding returned stakes)`}. This cohort is not this selection’s measured accuracy.</p>
 <ul class="mt-3 space-y-2 text-xs">{#each pick.evidence.alternatives as other}<li>{other.selection} · model {pct(other.modelProb,1)} · {other.odds>1?'odds '+odds(other.odds):'Unpriced'}</li>{/each}</ul>
 </Accordion>
 <p class="mt-1 text-xs text-haze">{new Date(pick.kickoffTime).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'})} WAT</p></li>{/each}</ol><button class="btn-primary mt-4 w-full" onclick={preview}>{modelShortlist?'Replace working slip with shortlist':'Replace working slip & preview actions'}</button><p class="mt-3 text-xs text-haze">{#if modelShortlist}One option per fixture, ranked by model probability. This research shortlist is not an odds-qualified accumulator. {/if}Generated {new Date(generatedAt).toLocaleTimeString('en-NG',{timeZone:'Africa/Lagos'})} WAT. All matching options are listed below. Quoted search keeps up to eight alternatives per event within a bounded computation budget; global optimality is not guaranteed.</p>{:else}<p class="mt-5 text-haze">Choose your rules and generate a ticket. Each fixture contributes at most one selection.</p>{/if}<p class="mt-5 rounded-xl bg-ink p-4 text-xs leading-relaxed text-haze">Model estimates are not proven strike rates. Combined probability assumes independent matches; cross-match correlations can reduce accuracy. Higher win probability does not necessarily mean a profitable price. PuntersEdge does not place wagers.</p></section>
</div>

<Accordion title="All eligible fixtures & market options" count={shortlisted.length}>
 <p class="text-sm text-haze">Options below meet your sport, time, market and model percentage filters, ranked by Model % from highest to lowest. Unpriced options can be added manually; odds filters and target-odds ticket generation use quoted options only.</p>
 <div class="mt-4 grid gap-3 md:grid-cols-2">{#each shortlisted.slice(0,shortlistLimit) as pick}<div class="option-card min-w-0 p-4"><a class="fixture-name block min-h-8 break-words text-sm font-semibold hover:underline" href="/match?id={encodeURIComponent(pick.fixtureId)}">{pick.matchTitle}</a><p class="mt-1 break-words text-xs text-haze">{fixtureMetadataLines(enrichFixtureMetadata(pick,app.gameById(pick.fixtureId))).join(' · ')}</p><p class="mt-1 break-words text-sm">{pick.selection} · {pick.pricing==='quoted'?odds(pick.bestOdds):'Unpriced'}</p><p class="mt-1 text-xs text-haze">Model {pct(pick.modelProb,1)} · {pick.bookmaker} · value {pick.grade}</p><button class="btn-ghost mt-3 w-full" aria-pressed={app.inSlip(pick.id)} onclick={()=>choose(pick)}>{app.inSlip(pick.id)?'✓ Added · remove from slip':'+ Add to betslip'}</button></div>{/each}</div>
 {#if shortlisted.length}<button class="btn-primary mt-4" onclick={()=>app.slipOpen=true}>Open betslip · {app.slip.length} selections</button>{/if}
 {#if shortlisted.length>shortlistLimit}<button class="btn-secondary mt-4" onclick={()=>shortlistLimit+=30}>Show more eligible options</button>{:else if !shortlisted.length}<p class="mt-3 text-sm text-haze">Generate a shortlist with your filters to see eligible options.</p>{/if}
</Accordion>
